// ExamPage.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import './ExamPage.css';

const ExamPage = () => {
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes timer (300 seconds)
  const [answers, setAnswers] = useState({
    q1: "",
    q2: "",
    q3: "",
  });
  const navigate = useNavigate();

  useEffect(() => {
    if (timeLeft === 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  const calculateScore = () => {
    let score = 0;
    const correctAnswers = {
      q1: "4", // Answer to "What is 2 + 2?"
      q2: "Paris", // Answer to "What is the capital of France?"
      q3: "George Washington", // Answer to "Who was the first president of the United States?"
    };

    Object.keys(correctAnswers).forEach((key) => {
      if (answers[key].trim().toLowerCase() === correctAnswers[key].trim().toLowerCase()) {
        score += 33.33; // Each correct answer is worth approximately 33.33 points
      }
    });

    return Math.round(score); // Return rounded score
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const score = calculateScore();
    alert(`Exam submitted! Your score is ${score}`);
    navigate("/view-scores", { state: { score } }); // Pass score to ViewScores
  };

  const handleChange = (e) => {
    setAnswers({
      ...answers,
      [e.target.name]: e.target.value,
    });
  };

  return (
    <div className="exam-container">
      <h2>Exam</h2>
      <div className="timer">
        <p>Time Left: {Math.floor(timeLeft / 60)}:{timeLeft % 60}</p>
      </div>

      <form onSubmit={handleSubmit} className="exam-form">
        <div className="question">
          <label>1. What is 2 + 2?</label>
          <input
            type="text"
            name="q1"
            value={answers.q1}
            onChange={handleChange}
            required
          />
        </div>

        <div className="question">
          <label>2. What is the capital of France?</label>
          <input
            type="text"
            name="q2"
            value={answers.q2}
            onChange={handleChange}
            required
          />
        </div>

        <div className="question">
          <label>3. Who was the first president of the United States?</label>
          <input
            type="text"
            name="q3"
            value={answers.q3}
            onChange={handleChange}
            required
          />
        </div>

        <button type="submit" className="submit-btn">Submit Exam</button>
      </form>
    </div>
  );
};

export default ExamPage;
